from typing import List
class Solution:
    def countTestedDevices(self, batteryPercentages: List[int]) -> int:
        b = batteryPercentages[:]
        n = len(b)
        count = 0
        for i in range(n):
            if b[i] > 0:
                count += 1
                for j in range(i + 1, n):
                    b[j] = max(0, b[j] - 1)
        return count

c.cpp:
class Solution {
public:
    int countTestedDevices(vector<int>& batteryPercentages) {
        vector<int> b = batteryPercentages;
        int n = b.size(), count = 0;
        for (int i = 0; i < n; ++i) {
            if (b[i] > 0) {
                ++count;
                for (int j = i + 1; j < n; ++j) b[j] = max(0, b[j] - 1);
            }
        }
        return count;
    }
};

