class Solution {
    public int countTestedDevices(int[] batteryPercentages) {
        int[] b = batteryPercentages.clone();
        int n = b.length, count = 0;
        for (int i = 0; i < n; ++i) {
            if (b[i] > 0) {
                ++count;
                for (int j = i + 1; j < n; ++j) b[j] = Math.max(0, b[j] - 1);
            }
        }
        return count;
    }
}

